(function(){'use strict';const $=s=>document.querySelector(s),owner=KashierData.userId(),key='kashier.restore.v1.'+owner;let id=null,pending=null,prepared=null,busy=false,epoch=0,state=null,blocked=false;
const active=()=>owner&&KashierData.loggedIn()&&KashierData.userId()===owner,status=t=>$('#restore-status').textContent=t;
function controls(){for(const name of ['restore-file','restore-hash','restore-check','restore-state','restore-ack'])$('#'+name).disabled=busy||blocked;$('#restore-submit').disabled=busy||blocked||!prepared||state?.status!=='empty'||!$('#restore-ack').checked;}
function clear(){prepared=null;$('#restore-result').hidden=true;$('#restore-receipt').textContent='';$('#restore-preview').hidden=true;$('#restore-count').textContent='';$('#restore-ack').checked=false;controls();}
function show(v){state=v;if(v.status==='committed'){clear();$('#restore-result').hidden=false;$('#restore-receipt').textContent=v.request_id+' · '+v.record_count+' تۆمار · '+v.completed_at;status('گەڕاندنەوە تەواو بوو. کارمەندەکان ڕاگیراون؛ دەسەڵات و ڕەزامەندیی نوێ پێویستن.');}else{$('#restore-result').hidden=true;status(v.status==='empty'?'هەژمارەکە بەتالە. فایل و کۆدی پارێزراو پشکنە.':'هەژمارەکە داتای هەیە؛ گەڕاندنەوە ڕەت کرایەوە.');if(v.status!=='empty')clear();}controls();}
async function account(){if(!active())throw Error('هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.');const a=await KashierData.getAccount();if(!active()||a.id!==owner)throw Error('ناسنامەی هەژمار پشتڕاست نەکرایەوە.');}
async function readState(){const v=await KashierData.getOwnerRestoreStatus(id);if(!active())throw Error('هەژمارەکە گۆڕاوە.');return RestoreModel.state(v,owner,id,pending?.sha256);}
async function checkState(){if(busy||blocked)return;const life=epoch;busy=true;controls();try{await account();const v=await readState();if(life!==epoch)return;show(v);}catch(e){if(life===epoch){clear();status(e.message);}}finally{busy=false;controls();}}
$('#restore-form').addEventListener('submit',async e=>{e.preventDefault();if(busy||blocked)return;const life=++epoch;clear();busy=true;controls();try{await account();const file=$('#restore-file').files?.[0],hash=$('#restore-hash').value.trim();if(!file||file.size<1||file.size>25*1024*1024)throw Error('فایلێکی JSON تا ٢٥ MiB هەڵبژێرە.');const buffer=await file.arrayBuffer(),checked=await ExportFile.verify(buffer,owner,hash);if(checked.version!==7)throw Error('گەڕاندنەوە تەنها بۆ وەشانی ٧ بەردەستە.');if(pending&&pending.sha256!==checked.sha256)throw Error('هەمان فایل و کۆدی داواکاریی پێشوو هەڵبژێرە.');const v=await readState();if(life!==epoch||!active())return;show(v);if(v.status==='empty'){prepared={raw:new TextDecoder().decode(checked.bytes),sha256:checked.sha256};$('#restore-count').textContent=String(checked.total);$('#restore-preview').hidden=false;status('فایل و هەژماری بەتال پشتڕاست کرانەوە. مەرجەکان بخوێنەرەوە و پشتڕاست بکەرەوە.');}}catch(e){if(life===epoch){clear();status(e.message);}}finally{busy=false;controls();}});
$('#restore-submit').addEventListener('click',async()=>{if(busy||blocked||!prepared||state?.status!=='empty'||!$('#restore-ack').checked)return;const life=epoch,file=prepared;busy=true;controls();try{await account();const v=await readState();if(life!==epoch||!active())return;if(v.status!=='empty'){show(v);return;}pending=RestoreModel.pending({owner,id,sha256:file.sha256},owner);const saved=JSON.stringify(pending);sessionStorage.setItem(key,saved);if(sessionStorage.getItem(key)!==saved)throw Error('ناسنامەی داواکاری پاشەکەوت نەکرا؛ گەڕاندنەوە دەست پێ نەکرد.');if(life!==epoch||!active())return;status('گەڕاندنەوە لە جێبەجێکردندایە…');const result=await KashierData.restoreOwnerData(id,file.raw,file.sha256);if(life!==epoch||!active())return;const checked=RestoreModel.state(result,owner,id,file.sha256);if(checked.status!=='committed')throw Error('بەڵگەی تەواوبوون وەرنەگیرا.');show(checked);}catch(e){if(life===epoch){clear();state=null;status(e.message+' بۆ دڵنیابوون دوگمەی «پشکنینی ئەنجام» دابگرە؛ فایلەکە بپارێزە.');}}finally{busy=false;controls();}});
$('#restore-state').addEventListener('click',checkState);$('#restore-ack').addEventListener('change',controls);for(const [name,event] of [['restore-file','change'],['restore-hash','input']])$('#'+name).addEventListener(event,()=>{epoch++;clear();});window.addEventListener('pagehide',()=>{epoch++;clear();$('#restore-file').value=$('#restore-hash').value='';$('#restore-result').hidden=true;$('#restore-receipt').textContent='';status('');});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
try{if(!active()){location.replace('auth.html?next=restore.html');return;}const raw=sessionStorage.getItem(key);if(raw){pending=RestoreModel.pending(JSON.parse(raw),owner);id=pending.id;}else id=crypto.randomUUID();clear();checkState();}catch(e){blocked=true;clear();status(e.message);}
})();
